NOTES={}
def add(n, intervals, context, hints, observation, issues=''):
 NOTES[n]=dict(candidate_intervals_seconds=intervals,context_intervals_seconds=context,delta_hints=hints,observation=observation,issues=issues)
add(1,[(852.5,858.5)],[(841,894)],['Bản tin có hình ảnh một nhóm người đứng trước công trình phục vụ phóng tàu vũ trụ.','Bốn người đứng thành hàng sát nhau, cùng mặc áo thun đen.','Sau hình ảnh nhóm người là cảnh tên lửa trên bệ phóng và tên lửa phun lửa.'],'Bốn người áo đen thấy rõ ở 853.567 và 856.567; tiếp theo tên lửa rồi mô phỏng Trái Đất.','Thông tin nhiệm vụ cực quang mới được ASR gợi ý, chưa nghe xác minh; H3 dùng trình tự hình ảnh, cần context. Query nguồn cần kiểm tra speech.')
add(2,[(379,397.5)],[(359.5,397.5)],['Bản tin quay những con hổ trong khu nuôi dưỡng.','Một nhóm hổ con đi lại và chơi trên bãi cỏ.','Các hổ con trèo qua những đoạn ống màu đen đặt sát mặt đất.'],'Hổ trưởng thành nằm trong chuồng, sau đó hổ con ngoài bãi cỏ; lower-third nói Đồng Nai, 2 hổ mẹ Bengal sinh 5 con.','Số lượng sinh và địa điểm được chữ trên màn hình hỗ trợ trong context, không phải mọi frame hổ con.')
add(3,[(25,27),(291,295)],[(22,33),(281,300)],['Hai người phụ nữ cho dê ăn trong một khu chuồng có mái che.','Một người mặc áo trắng quàng áo đỏ trên vai; người kia mặc áo sọc tím.','Hai người cầm bó lá xanh đưa qua hàng rào gỗ cho những con dê trắng.'],'Hai đoạn lặp cảnh hai phụ nữ đưa lá cho dê; toàn trại là shot bối cảnh riêng.','Giữ hai đoạn riêng; không nối qua hơn bốn phút.')
add(4,[(254,266)],[(250,266)],['Một người đang bày các cuốn thức ăn lên đĩa.','Các cuốn có lớp vỏ vàng và tím, bên trong thấy rau xanh cuộn chặt.','Đĩa chữ nhật lòng xanh có lá xanh và các bông hoa nhỏ màu vàng, tím.'],'Bàn tay đeo găng đặt các cuốn đứng trên đĩa xanh, có hoa trang trí.','Chưa xác minh loại đậu hũ và tên hoa pansy; không đưa tên nguyên liệu này vào hint.')
add(5,[(436,439),(996,1000)],[],['Một con chim đứng trên lớp lá khô dưới gốc cây lớn.','Con chim có đầu và thân sẫm ánh xanh, cánh màu nâu đỏ.','Mắt của con chim có màu đỏ nổi bật.'],'Hai đoạn lặp chim mắt đỏ dưới gốc cây, hai bên là cảnh thuyền/cây và cảnh bắt cá.','Không suy loài chim hay phân bố Nam Bộ từ ngoại hình.')
add(6,[(733,736.8)],[(722,737)],['Một em nhỏ đứng cạnh quầy bán đồ ăn ở lễ hội ngoài trời.','Em đeo một vật hình con mực màu đỏ và cầm túi giấy.','Phần đầu con mực đỏ ôm quanh khuôn mặt em; em mỉm cười và giơ tay chào.'],'Vật đỏ bao quanh đầu, xúc tu xuống ngực; túi giấy tím chữ vàng, trước quầy đồ ăn.','Query nguồn nói đeo trước ngực chưa mô tả đủ vị trí; danh hiệu lễ hội lớn nhất chưa được xác minh.')
add(7,[(202,206)],[(191,209)],['Hai người phụ nữ ngồi trò chuyện giữa những đống dứa ngoài vườn.','Người trẻ mặc áo hồng quàng khăn, ngồi đối diện người phụ nữ lớn tuổi bên giỏ nhựa vàng.','Phía sau có người đội nón lá và một chiếc ghe xanh sát bờ.'],'Khung rộng 202–205s thấy đủ người, giỏ, dứa, ghe và nón lá.')
add(8,[(119,123)],[],['Ba người ngồi cạnh nhau chơi nhạc cụ kim loại hình tròn bằng tay.','Người mặc áo sáng màu ngồi giữa hai người mặc áo đen.','Phía sau họ là kệ nhiều ô chứa sách; mặt nhạc cụ có những vùng lõm hình tròn.'],'Shot ba người trước kệ sách ở 119.44–122.44, sau đó chuyển cận nam áo đen.')
add(9,[(121,125),(183,186.9)],[(117,125),(174,186.9)],['Một chàng trai ngồi cạnh các mảnh vật liệu dựng trên một chiếc hộp.','Anh đội mũ đen và mặc áo trắng có chữ; ánh đèn chiếu các mảnh vật liệu lên tường.','Bóng trên tường ghép thành chân dung một người đàn ông mặc vest.'],'Hai lần xuất hiện cùng bố cục; chân dung hoàn chỉnh ở khoảng 122–124 và 183–186s.','Không xác minh chất liệu bìa chỉ từ ảnh; khoảng cuối tới EOF cần probe.')
add(10,[(111,116.5)],[(91,98),(107,116.5)],['Một người đang vệ sinh bộ phận máy ảnh trên bàn.','Ống kính đã tháo rời được đặt trên khăn tím hồng, cạnh thân máy ảnh.','Bàn tay dùng một que nhỏ đầu trắng lau phần bên trong ống kính.'],'Cảnh tháo máy trước cuộc phỏng vấn; cảnh khăn và lau lens sau đó.','Trình tự nguồn bị ngắt bởi phỏng vấn; không nối toàn khoảng làm answer.')
add(11,[(674,677),(893.5,899.5)],[(672,680),(890,927)],['Một tác phẩm điêu khắc bằng cát được trưng bày ngoài trời.','Tác phẩm có ba nhân vật ở tư thế chơi thể thao với ván và giày trượt.','Phía sau các nhân vật là mảng trang trí hình vòm lớn; phần sau bản tin có những vệt khói hồng trên trời.'],'Cảnh lặp trong teaser và bản tin chính; khói hồng ở shot sau, không cùng tồn tại với tượng.','GT frame cũ và start,end trỏ hai lần phát khác nhau, đều có cảnh phù hợp; H3 là context.')
add(12,[(99,101)],[],['Một nhóm trẻ em và thiếu niên đứng nhận quà trước phông nền đỏ.','Hai người đàn ông mặc sơ mi hồng và trắng đứng hai đầu nhóm.','Các em cầm bảng hỗ trợ; phía trước là túi quà trắng, phông nền có chữ Chợ Tết và năm 2024.'],'Nhóm trẻ cầm bảng ở 99.64–100.64; cần ảnh lớn để xác minh toàn văn bảng.','Không xác minh toàn văn bảng hoặc logo y tế ở ảnh overview.')
add(13,[(216,221)],[],['Các ly món tráng miệng được xếp trên đĩa tròn màu trắng.','Bàn tay lần lượt thêm hai ly vào đĩa đã có sẵn một ly.','Mặt mỗi ly có trái cây đỏ và lá xanh; cạnh đĩa có hai bông hoa đỏ sẫm và vàng.'],'216s một ly; 217–218s thêm ly thứ hai; 220s thêm ly thứ ba.','Tên panna cotta và bạc hà chưa được nghe đối chiếu; hint chỉ mô tả nhìn thấy.')
add(14,[(558,564),(609,615)],[(556,615)],['Một bản tin quay bãi biển có người tắm và các đồ vật mang hình cá mập.','Có bảng cảnh báo với ảnh cá mập ở lối vào bãi biển.','Trong cửa hàng xuất hiện mô hình hàm cá mập lớn và áp phích chữ JAWS.'],'Cảnh bảng WARNING 559–562, cửa hàng hàm cá và JAWS 610–613.','Không có cá mập thật được quan sát trong đoạn; hai answer candidates dựa trên context nhiều shot; năm phim/đạo diễn chỉ là thông tin nguồn chưa xác minh.')
add(15,[(130,143.5)],[],['Góc máy từ trên cao theo dõi ba tay đua xe đạp đi thành một hàng.','Ba tay đua mặc áo sáng màu và quần có mảng vàng xanh.','Người đi đầu đội mũ trắng, người thứ hai mũ đỏ, người cuối mũ sẫm; đường có dải phân cách trồng cây.'],'Ba tay đua liên tục trong shot trên cao, trước và sau là nhóm áo khác.','Cần ảnh lớn để xác nhận màu mũ cuối và khẳng định cùng đội; không suy đội chỉ từ áo.')
add(16,[(74,81)],[(40,54),(74,81)],['Một phụ nữ lớn tuổi cầm sách trong căn phòng có nhiều giá sách.','Người phụ nữ mặc áo khoác tím nhạt trên áo hoa và nhìn xuống quyển sách đang mở.','Bìa sách có chân dung đen trắng cùng dòng chữ trắng, nền bìa tông nâu vàng.'],'Đọc sách đứng ở 44–52 và cầm sách bìa chân dung ở 78–80.','Chi tiết xâu hạt cần cận cảnh; H3 chỉ ở đoạn sau, không gộp hai đoạn thành answer chung.')
add(17,[(40,42.5)],[(17,24),(35,42.5)],['Một con mèo đeo vòng cổ nằm trong phòng nuôi nhiều mèo.','Con mèo có lông vằn nâu xám và nằm trên bề mặt màu hồng nhạt.','Dưới cổ mèo có bảng tên hình khúc xương ghi Nà Ní.'],'Mèo bảng tên ở 41.44; trước đó là các mèo khác bên bát ăn.','Chi tiết tô úp trên thùng đỏ chưa được chứng minh trong overview; cần đối chiếu chữ bảng tên bằng crop.')
add(18,[(441,445.5)],[(431,435),(441,445.5)],['Trẻ em chơi dưới dòng suối có nước chảy qua các bậc đá.','Một em mặc áo đen có mảng vàng ngồi ngay cạnh dòng nước đổ xuống.','Sau góc quay gần là góc rộng thấy những em khác đứng trên bậc đá và dưới dòng nước.'],'Nhóm ngồi dưới bạt ở 432–434, phỏng vấn 436–440, trẻ áo đen vàng 442–444.','Query mô tả trình tự nhưng có phỏng vấn chen giữa; bạt chỉ ở context.')
add(19,[(675,687)],[(666,687),(697,703)],['Cận cảnh một miếng kim loại có nhiều lỗ được đục thành hàng.','Một bàn tay giữ miếng kim loại cạnh chiếc đinh, mặt trong có màu trắng.','Mặt ngoài các lỗ nhô lên; ở cảnh khác miếng này được dùng để bào một củ màu trắng.'],'Mặt trong/đinh 676–678, mặt lỗ nhô 680–686, bào củ 698–702.','Không xác định hợp kim thiếc bằng hình ảnh; công dụng ở context riêng.')
add(20,[(119,122.5)],[(115,122.5)],['Bàn tay đeo găng đang bóc vỏ một con tôm đã chín.','Con tôm màu cam được giữ trên tô thủy tinh chứa vỏ tôm.','Sau đó tôm được đặt lên đĩa trắng cùng những con tôm đã bóc vỏ.'],'Bóc vỏ 115–119, đĩa có tôm 121.72.','Cần kiểm tra dày hơn lúc đặt tôm và đếm năm con có sẵn; không suy đây là con cuối từ một ảnh.')
add(21,[(219.5,233.5)],[],['Màn hình ghép ba video dọc của những người phụ nữ nói trước máy quay.','Ở bố cục đầu, hai ô trái có áo trong màu vàng xanh, ô phải có áo trong màu sẫm và chữ đặt khác vị trí.','Sau đó đổi sang bộ ba khác, trong đó người ở ô giữa có tóc ngắn hơn hai người hai bên.'],'Bố cục ba ô đầu 220–224; đổi nhóm 226–232.','Không khẳng định là cùng một người chỉ từ ảnh; chủ đề y khoa được chữ tiêu hóa/có thai hỗ trợ.')
add(22,[(272,274)],[(253,274)],['Một nhóm người tập giãn cơ trên con đường trước dãy nhà.','Họ ngồi giang chân, cúi người và đưa tay về phía bàn chân.','Người mặc áo đỏ xanh đứng hướng dẫn; trong nhóm có những người đội mũ đỏ.'],'Giãn chân dưới đất 253–261; người hướng dẫn 265–271; hàng người rộng ở 272–273.','Seed không cho thấy mọi người đồng thời chạm mũi chân; chưa đủ bằng chứng chỉ một người đeo kính và đúng ba mũ đỏ. Cần mở rộng cảnh.')
add(23,[(128.5,139)],[(110,139)],['Một công trình chắn ngang dòng nước được quay từ trên cao.','Phần giữa công trình có nhiều trụ và các tấm kim loại nối thành hàng.','Trước đó là bản đồ các tuyến kênh; sau cảnh trên cao là cận cảnh các tấm chắn sát mặt nước.'],'Bản đồ kênh Hà Tiên–Rạch Giá và T3/T4/T5; công trình 129–134, cận 135–138.','Chưa thấy đủ bốn lần xuất hiện công trình; không khẳng định trời mưa chỉ từ gợn nước.')
add(24,[(654,666.8)],[(654,678)],['Một nhóm sư tử ở khu nuôi dưỡng có các bục gỗ.','Các sư tử nhỏ đứng rồi nằm trên bục sát một bảng màu đen.','Trên bảng có dòng chữ LONDON ZOO màu xanh lá.'],'Sư tử và bảng London Zoo cùng hiện 654–666; sau đó phỏng vấn nữ áo xanh.','Cần mở rộng để xác minh cảnh hai nhân viên cân con vật.')
add(25,[(201,205)],[(201,218)],['Một người đang xào mực trong chảo sáng màu trên bếp.','Người đó đổ các miếng đậu xanh từ tô thủy tinh vào chảo rồi đảo bằng xẻng gỗ.','Bên cạnh chảo có đĩa hành tây trắng và ớt đỏ đã thái.'],'Đổ đậu 201–204, hành tây tiếp theo 205–207.','Cảnh lắc chảo slow motion ở phía sau cần mở rộng; không dùng toàn đoạn trò chuyện làm answer.')
add(26,[(726,731)],[(722,731)],['Một người đàn ông mặc vest xanh ngồi trên ghế tựa lớn.','Ông cầm khối đá sáng màu bằng hai tay, đưa gần mặt để nhìn.','Bên phải có phụ nữ mặc đồ đen, quàng khăn hồng tím và mỉm cười.'],'Cận đá 722–725, khung rộng đủ hai người 726–730.','Mỏ lộ thiên sau đó chưa thấy trong overview; giữ context riêng sau khi mở rộng.')
add(27,[(144.5,148),(150,153)],[(144.5,153)],['Cà rốt cắt hình ngôi sao được chần trong nồi nước sôi.','Các miếng cà rốt nằm trong rổ lưới kim loại, có đôi đũa gỗ đảo bên trong.','Nồi thủy tinh màu hổ phách đặt trên bếp; sau đó rổ cà rốt được nhấc lên khỏi nước.'],'Ngôi sao cam rõ; ngắt shot người dẫn 148–149 rồi quay lại rổ 150–152.','Nguồn kéo dài đến món hoàn thiện, chưa thấy trong cửa sổ seed; cần context bổ sung.')
add(28,[(216,228)],[],['Một người dùng đũa xếp nguyên liệu lên đĩa đặt trong nồi hấp.','Những thanh đỏ trắng được xếp xen với các lát màu cam hình hoa.','Sau đó người này dùng muỗng lấy hỗn hợp từ tô thủy tinh đặt vào giữa đĩa.'],'Thêm thanh đỏ trắng 216–217, hoa 218–222, múc hỗn hợp giữa 223–227.','Trùng nguyên văn, video và seed với query 33.')
add(29,[(451,455.5)],[],['Cận cảnh một người thu hoạch chùm nho xanh trên giàn.','Một tay đỡ chùm nho, tay kia dùng kéo cán đen cắt phần cuống.','Gần cuống có dây buộc màu xanh dương; sau khi cắt chùm nho được hạ xuống.'],'451–455 có kéo, dây xanh và cắt; 456 chuyển giỏ.')
add(30,[(276,284)],[(269,288)],['Một cảnh quay chậm ghi đoàn xe đạp đi qua vạch đích từ góc thấp sát đường.','Trong nhóm đầu có tay đua áo vàng và các tay đua áo xanh.','Mặt đường có vạch vàng chéo, phía sau là khán giả và bảng TÔN ĐÔNG Á.'],'Shot REPLAY từ269; nhóm đi qua 276–284.','Thứ tự nhất nhì ba trong nguồn chưa được xác nhận; góc thấp cho thấy áo xanh vượt vạch trước áo vàng trong các mẫu. Cần kiểm tra liên tục, không giữ thứ tự nguồn trong hint.')
add(31,[(105,111)],[(101,111)],['Nhiều người mặc áo và đội mũ xe ôm công nghệ chờ tại trạm xăng.','Có người di chuyển xe qua phía trước nhóm đang đứng cạnh xe máy.','Dưới khung hình là bảng giá dầu, gồm dòng Dầu Mazut; cảnh trước đó là tay đóng nắp bình xăng.'],'Nắp bình 103–104, nhóm xe ôm 105–110 với bảng giá.','Chưa đếm đủ bốn tài xế và hướng di chuyển; cần kiểm tra dày hơn.')
add(32,[(247,260)],[(237,260)],['Một người làm việc trên mặt nước khi trời còn tối và lúc hửng sáng.','Người đó đeo đèn trên đầu, ở cạnh một chiếc thuyền nhỏ.','Các cảnh sau quay mặt nước rộng dưới bầu trời xanh tím và dải mây hồng.'],'Người đeo đèn trên thuyền 237–239, người đứng nước và thuyền 247–251.','Hành động kéo lưới và nhóm dùng máy quay chưa thấy trong cửa sổ đầu; cần mở rộng.')
NOTES[33]={**NOTES[28], 'issues':'Trùng nguyên văn, video, seed và cảnh mục tiêu với query 28; giữ provenance, không tính nhiệm vụ độc lập.'}
add(34,[(229,253)],[],['Một người cho bún vào tô trắng rồi múc thức ăn và nước dùng lên trên.','Trong tô thấy các miếng thịt có da vàng, cà rốt cam, những thanh dài xanh vàng và nguyên liệu sẫm màu.','Tô có hai quai; cạnh tô là chén nước chấm nhỏ, cuối đoạn có lá xanh được đặt lên trên.'],'Cho bún 230–232, múc thịt và nước 233–246, zoom tô 247–250, lá xanh 251–252.','Thứ tự nguồn nói lá xanh trước zoom nhưng ảnh cho thấy zoom trước rồi mới thêm lá; ghi xung đột, không giữ thứ tự sai.')
add(35,[(486,493.5)],[(476,500)],['Một con lân vàng biểu diễn trên dãy cột cao trong sân khấu ngoài trời ban đêm.','Con lân nhảy sang cột bên cạnh rồi cúi đầu xuống vật màu cam.','Sau cảnh cận đầu lân sát vật màu cam và hoa vàng là cảnh lân đứng thẳng trên cột.'],'Đứng xoay 476–485, nhảy 486–488, cúi 489–492, đứng 493.','Tên quả bí và số lần nhảy cần clip dày hơn; mô tả màu vật được quan sát.')
add(36,[(248,251)],[(247,258)],['Một nhóm người đi xuống lối dốc giữa các căn nhà trong trời mưa.','Người đi sau mặc áo mưa sáng màu và cầm ô tím.','Mặt lưng áo mưa có hình in cùng chữ; sau đó là nhóm người đi trên đường đất cạnh ao.'],'Người cầm dù và áo mưa 248–250; nhóm cạnh ao 251–257.','Chưa rõ hình in có phải con gấu; không dùng nhận định này làm hint.')
add(37,[(506,508),(518,522)],[(506,522)],['Một bản tin quay các đầu bếp chế biến và bày món tôm.','Có đĩa tôm chín màu cam ở tiền cảnh, phía sau là những ổ bánh mì vàng.','Các cảnh sau cho thấy đầu bếp làm việc trên bàn trải khăn đỏ và tôm bổ đôi được nướng trên vỉ.'],'Đĩa tôm và bánh 506–507; nhóm chế biến 508–517; vỉ nướng521.','Số ba ổ bánh và động tác đặt bánh cần kiểm tra dày; khoảng kết thúc còn mở.')
add(38,[(649,675)],[],['Một nữ giáo viên mặc áo dài hồng đứng cạnh bảng xanh trong bài học tiếng Anh.','Trên bảng có từ remember và nhánh V-ing kèm giải thích bằng tiếng Anh.','Dòng ví dụ có cụm remember reading something in the paper.'],'Bảng remember / V-ing và ví dụ rõ; cô giáo bên phải laptop.','Hai biên cửa sổ vẫn cùng bài giảng, cần mở rộng để tìm bắt đầu/kết thúc; kính chưa rõ.')
add(39,[(1061,1079)],[],['Một giáo viên nam mặc sơ mi trắng và cà vạt giảng bài bên cạnh slide.','Slide có sơ đồ ba tầng với hai ô ở trên, một ô giữa và hai ô phía dưới.','Khung trên tông cam, ô giữa xanh, khung dưới xanh lá; tiêu đề nói về việc làm và hướng giải quyết.'],'Sơ đồ đầy đủ xuất hiện1061, tồn tại hết cửa sổ seed.','Biên kết thúc chưa thấy, cần mở rộng. Không dùng hết video như answer.')
add(40,[(353,368),(368,375)],[(353,375)],['Máy quay lia qua các sản phẩm đan thủ công màu nâu nhạt.','Lần lượt thấy túi có hoa, chậu hoa, bộ ấm tách rồi túi trang trí hoa đỏ.','Sau đó người phụ nữ bên trái cầm một chiếc tách nhỏ khi trò chuyện với người bên phải.'],'Lia qua sản phẩm353–367, cầm tách368–374.','Chất liệu lục bình chưa được nghe xác minh; hai answer dạng hành động khác nhau cần context.')
add(41,[(262,268)],[],['Hai học sinh đứng cầm micro và giấy đọc trên sân khấu trường học.','Cả hai mặc áo trắng, quần ngắn xanh và khăn quàng đỏ.','Phía sau có bộ trống đỏ, đàn phím và phông tím ghi LEADERSHIP DAY - STEAM FAIR 2021.'],'Đúng cảnh 262–267; trước và sau là cảnh khác của phóng sự.')
add(42,[(0,24)],[(0,24)],['Một nhóm người mặc đồ tối biểu diễn bên con lân vàng trên sân khấu.','Những người này chạy, nhảy và tụ lại gần nhau trước dãy cột.','Một người mang vật tròn màu cam gắn hoa vàng đi vào giữa các cột.'],'Nhóm biểu diễn0–21, vật cam được mang22–23.','Cửa sổ seed chưa có người thức dậy đánh thức lân; cần mở rộng. Không tự gọi vật cam là bí thật.')
add(43,[(744,748)],[(744,760)],['Một người dùng điện thoại chụp tranh động vật trên tường ngoài phố.','Người đó mặc áo đen và quần hồng, đứng trước bức tranh tê giác lớn.','Hình tê giác nằm phía trên một chiếc ô tô màu bạc đậu sát tường.'],'Chụp ảnh 744–747, cận tê giác và xe748–752.','Cảnh ba con khỉ trên cầu cần mở rộng, không cùng tồn tại trong answer tê giác.')
add(44,[(7,10.6),(21,24.5)],[],['Con lân vàng biểu diễn trên các cột cao trong một video dọc.','Con lân chúi đầu rồi rơi hoặc nhảy xuống từ cột.','Ngay cạnh vị trí rơi có mô hình chiếc tàu nhỏ màu xanh dương.'],'Lặp hai lần cảnh lân xuống7–10 và21–24; mẫu26.44fps không dùng chia25.','Không phân biệt nhảy chủ ý hay té bằng ảnh thưa; cần kiểm tra dày. Thời gian dựa trên video PTS.')
add(45,[(27,31)],[],['Hai người treo một tấm băng-rôn trước cửa một tòa nhà.','Băng-rôn có nền xanh và dòng chữ CÙNG EM ĐẾN TRƯỜNG.','Trên băng-rôn có ảnh hai em nhỏ mặc áo vàng cùng hình phong cảnh và con đường.'],'Hai người căng banner27–30, người đi qua tiền cảnh.','Chi tiết ảnh nhỏ cần crop độ phân giải cao.')
add(46,[(869,872)],[(861,864),(869,878)],['Một tay đua xe đạp mặc áo đỏ cầm chai nước sát mặt trong lúc đang đạp xe.','Tay đua đội mũ trắng có mảng xanh vàng và đeo kính.','Ở cảnh khác có hai tay đua áo sẫm và đen cam bám đuổi nhau trên đường.'],'Tay đua đỏ869–871; hai người861–863 và875–877.','Mô tả nguồn dễ hiểu nhầm hai người và người áo đỏ chung khung hình; thực tế là các shot khác nhau.')
add(47,[(828,835)],[(816,841)],['Đoạn quay trên đường từ phía sau các xe máy đang chạy.','Có người nằm thấp trên yên xe; một ô tô xanh và người đi xe máy áo xanh cùng xuất hiện.','Video phóng to rồi dùng các vòng tròn đỏ khoanh hai xe máy.'],'Hai vòng đỏ đồng thời rõ ở831.44, sau đó còn một vòng.','Không suy tốc độ cao từ ảnh; cần clip chuyển động cho hành vi và khoảng hai vòng.')
add(48,[],[],['Một người xào các miếng nguyên liệu trắng trong chảo.','Chảo có thành ngoài màu cam đỏ và dùng xẻng gỗ để đảo.','Các đoạn rau xanh dài được cho vào để trộn cùng nguyên liệu trắng.'],'Seed179s là đổ nguyên liệu trắng ra đĩa; sau đó chảo trống và cho rau193s.','Cần mở rộng sau193 để tìm đúng giai đoạn trộn; không nhận seed làm GT.')
add(49,[(144,156)],[],['Một nguyên liệu dài xiên trên que được lăn qua các lớp phủ trên đĩa.','Đầu tiên là lớp rau xanh và hạt đỏ băm nhỏ, sau đó là bột trắng.','Người chế biến xoay que cho bột bám kín rồi đặt riêng trên đĩa trắng.'],'Các bước lần lượt144–147,148–152,153–155; không cần đoán tên nguyên liệu.')
add(50,[(170,186)],[],['Một nữ đầu bếp đảo món xào nhiều màu trong chảo đen.','Trong chảo có miếng thức ăn vàng, hạt nâu, ớt xanh đỏ và hành tím.','Sau khi tắt lửa, cô thêm vỏ chanh bào và nước cốt chanh rồi trút món ăn ra đĩa.'],'Đảo170–174, tay tắt bếp175–176, chữ VỎ CHANH MÀI180 và NƯỚC CỐT CHANH182–183, trút184–185.','Biên cuối còn món đang đổ; cần kiểm tra thêm vài giây.')
add(51,[(23,26)],[],['Góc quay gần ba tay đua xe đạp đang đi sát nhau.','Hai người mặc áo xanh và đội mũ đỏ, trắng; người cạnh họ mặc áo vàng.','Dưới quai mũ đỏ có sợi màu trắng rủ xuống bên cổ tay đua.'],'Cận mũ đỏ21–22, đủ ba người23–25, đổi nhóm26.','Cần crop để xác nhận chi tiết dây trắng, không đoán đó là tai nghe.')
add(52,[(16,34)],[],['Máy quay giới thiệu các nguyên liệu nấu ăn bày trên bàn.','Cảnh gần đi từ những loại hoa nhiều màu sang đĩa tôm rồi phần nguyên liệu xay màu hồng.','Sau các cảnh cận là khung hình rộng bày toàn bộ nguyên liệu cùng các chén gia vị.'],'Hoa16–19, tôm20–22, phần hồng23–25, quay lại hoa26–27.','Cần xem phần còn lại để xác định cảnh tĩnh toàn bộ; chưa xác nhận nguyên liệu thứ hai là hải sản từ hình ảnh.')
add(53,[(682,684),(691,693)],[(682,703)],['Hai người phụ nữ ngồi làm đồ thủ công trên một sàn gỗ.','Người lớn tuổi mặc áo xanh ô liu, người trẻ mặc váy xanh có hoa văn.','Căn phòng có các cửa sổ chia ô lớn và một hàng vật tròn treo phía trên; phía trước có chiếc võng.'],'Hai người rõ ở 682–683 và 691–692; góc rộng căn phòng 694–702.','Chưa xác nhận số lượng mười vật treo hoặc công dụng thớt; H3 là context.')
add(54,[(77,85)],[],['Một sân khấu có các chữ lớn đặt sát mép phía trước.','Phía sau người biểu diễn mặc đồ xanh là màn hình với các đường xoắn tròn màu vàng.','Các chữ nổi phía trước sân khấu ghi SẮC CỔ VIỆT.'],'Sân khấu và chữ cùng hiện 77–84; sau đó thay bố cục biểu diễn.')
add(55,[(96,103)],[],['Góc máy phía sau đi theo các tay đua xe đạp trên đường phố.','Các tay đua rẽ phải tại một giao lộ có đèn tín hiệu.','Đèn tín hiệu đang xanh; gần góc đường có biển chỉ dẫn nền xanh.'],'Theo sau xe đạp rẽ phải 96–102; 103 đổi góc trên cao.','Chưa xác nhận countdown 13, tên đường và số người; loại các chi tiết đó khỏi hint.')
add(56,[(1332,1347)],[],['Một slide bài giảng trình bày bảng số liệu về đô thị theo vùng.','Bảng có các con số được tô màu đỏ ở những hàng trên và màu xanh ở những hàng dưới.','Tiêu đề trên bảng là Phân bố đô thị không đồng đều giữa các vùng.'],'Bảng mới xuất hiện khoảng1332; tiếp tục hết cửa sổ.','Biên kết thúc chưa được bao phủ; cần mở rộng, không nhận1347 là end đã kiểm chứng.')
add(57,[(70,89)],[],['Một người dùng dao khứa các đường trên miếng mực trắng đặt trên thớt.','Miếng mực được lật và tiếp tục khứa, rồi được đưa lên cho thấy các đường cắt.','Chữ trên màn hình ghi MỰC LÁ KHỨA CA-RÔ.'],'Khứa70–81, trình bày82–88.','Các bước cắt sợi và nêm gia vị trong query chưa được xem; cần mở rộng context.')
add(58,[(269.5,275.5)],[],['Đoạn quay từ trên cao ghi lại các tay đua xe đạp về đích.','Người mặc áo xanh ở phía trước dang hai tay rồi giơ tay lên.','Phía sau là tay đua áo vàng cam; phía trước có cổng đỏ mang chữ ĐÍCH.'],'Dang tay270; giơ hai tay271–273; cổng274.','Không suy quốc tịch hay địa điểm từ hình ảnh.')
add(59,[(651,680)],[],['Bài giảng hiển thị một slide trắng với giáo viên nam đeo kính ở góc dưới trái.','Trên slide có ảnh người phụ nữ ngồi trên ghế với laptop trên đùi và cầm cốc.','Tiêu đề slide ghi Chọn “thời điểm vàng” để học; giáo viên mặc áo polo đen có hoa văn trên vai.'],'Cùng slide suốt cửa sổ651–680.','Áo giáo viên không khớp mô tả áo sọc của nguồn; hai biên chưa được bao phủ.')
add(60,[(549,566)],[],['Một bài giảng có giáo viên nữ ở góc dưới bên trái của slide trắng.','Phía trên slide có hình các nhân vật trắng đứng quanh một nhân vật đỏ.','Phía dưới bên phải xuất hiện hình hai người kéo co.'],'Hình kéo co xuất hiện khoảng549, còn tới hết cửa sổ.','Biên kết thúc chưa xác minh.')
add(61,[(263,266)],[(257,271)],['Góc nhìn từ trên cao hướng về những căn nhà trên sườn đồi xanh.','Cảnh nhà trên đồi xuất hiện giữa các cảnh một người đàn ông ngồi trong cabin cáp treo màu đỏ.','Người đàn ông mặc áo xanh, đeo kính; sau đó bước khỏi cabin tại khu vực có chữ NÚI SAM.'],'Nhà trên sườn đồi263–265; người trong cabin257–262, bước ra268–270.','H2 và H3 cung cấp context khác shot, không cùng tồn tại trong answer.')
add(62,[(216,236)],[],['Một người múc món nước có thịt từ nồi xanh sang một nồi nhỏ màu nâu nhạt.','Sau khi múc, người đó rắc rau xanh lên trên và dùng đũa chỉnh lại thức ăn.','Món ăn được thêm miếng ớt đỏ và những sợi vàng nhạt.'],'Múc217–225, rau227, đũa229, ớt233, sợi235.','Không xác định bộ phận thịt hoặc gọi sợi vàng là gừng khi chưa nghe xác minh.')
add(63,[(127,150)],[(127,156)],['Hai người đàn ông đứng cạnh những tấm ván có các hàng lỗ tròn.','Một người mặc áo kẻ ô, người kia mặc áo sáng màu và đội mũ xanh.','Sau cảnh người đàn ông cầm tấm ván là những tấm ván tương tự nổi trên mặt nước.'],'Hai người127–131; ván133–149; ván nổi151–155.','Công dụng và chất liệu cần thêm lời nói; H3 thuộc context.')
add(64,[(193,205)],[],['Góc quay phía trước ghi lại nhóm tay đua xe đạp tăng tốc trên đường.','Người mặc áo vàng đi cùng những tay đua áo xanh và sáng màu.','Máy quay theo nhóm tiến về đích, ở mép hình có đồ họa chỉ tốc độ.'],'Shot chính193–205 giữa cảnh trên cao và cảnh cổng.','Chưa xác nhận giá trị69 hoặc thứ tự thắng; không đưa vào hint.')
add(65,[(380,385.5)],[(380,406)],['Một đoạn video dọc quay nhóm người đưa xe máy qua khu vực đầy đất đá.','Nhóm người nâng chiếc xe máy lên giữa đống vật liệu đổ xuống đường.','Bản tin sau đó quay sườn đồi bị sạt và một hàng xe tải đang chờ.'],'Khiêng xe380–385; xe tải404.','Khoảng nguồn kết thúc400.7 bỏ sót xe tải; H3 nằm ngoài answer nhưng thuộc context; chưa xác nhận cách luồn đòn qua bánh.')
add(66,[(200,231)],[],['Một con lân màu trắng bạc biểu diễn trên dãy cột cao.','Con lân nhảy giữa các cột rồi giữ tư thế trên đỉnh cột.','Phía sau có hình rồng vàng; một góc quay gần cho thấy chân người biểu diễn trên cột.'],'Nhảy206–208 và220; chân226–230.','Số hiệu cột trong nguồn chưa đọc được; hình rồng không chứng minh rồng thật đang múa.')
add(67,[(75,78)],[(63,130)],['Một bản tin quay các căn nhà dựng sát dòng nước trong đô thị.','Có người phụ nữ mặc áo hồng đang rửa đồ bên nhà.','Các cảnh quay nhà ven nước xen với những cuộc phỏng vấn người dân.'],'Người áo hồng75; toàn phóng sự gồm nhà sát nước và ba lượt nhân vật trả lời.','Chưa quan sát được đầy đủ cảnh cầu và xe máy theo query; target chỉ là ứng viên cho moment người phụ nữ, chưa chứng minh đáp ứng toàn query.')
add(68,[(663,674)],[(654,710)],['Một người phụ nữ được phỏng vấn tại khu vực có nhiều quầy đồ ăn.','Một con mèo màu vàng cam nằm trên vai người phụ nữ.','Các cảnh xung quanh giới thiệu món bánh ép có hình con bạch tuộc lớn và người chế biến đồ ăn trên bếp.'],'Mèo trên vai666–672; bánh657–660.','Không xác minh danh hiệu lễ hội lớn nhất; H3 là context.')
add(69,[(61,89)],[(58,90)],['Đoạn quay từ trên cao theo dõi những tay đua xe đạp đang đổi vị trí dẫn đầu.','Nhóm đi qua một góc rẽ rồi tiếp tục trên đường thẳng có dải phân cách.','Trên dải phân cách ở góc rẽ có chữ WELCOME; trong nhóm có áo vàng và áo trắng.'],'Góc toàn61–65, rẽ67–71, đường thẳng73–89.','Thứ tự vượt chính xác chưa kiểm tra liên tục; đây là khoảng ứng viên rộng cho query nhiều hành động.')
add(70,[(140,184)],[(20,184)],['Một đầu bếp chế biến tôm trong chương trình nấu ăn.','Tôm được trộn trong tô rồi cho vào chảo, sau đó chuyển sang màu cam nâu.','Trước đó người dẫn cầm một trái bắp vàng; trên bàn có cà chua, dưa leo và hành tây.'],'Tôm140–180; người dẫn cầm bắp20 và nguyên liệu50–60.','Khoảng nguồn0–324 là gần toàn video; thu hẹp ứng viên. Mẫu10giây chưa đủ xác nhận biên hoặc thứ tự bốn loại rau.')
add(71,[(269,287)],[(229,287)],['Hai người đàn ông làm việc trên đất trong khu vườn có các trụ cây leo.','Một người mặc áo xanh dùng cuốc; gần đó có bao màu vàng.','Người còn lại mang bao tới rồi đổ vật liệu xuống đất.'],'Cuốc269–273, hai người277, đổ bao281–285.','Không xác định loại phân hoặc sản phẩm trong bao bằng hình ảnh.')
add(72,[(77,85)],[(65,85)],['Trẻ em tập bơi trong một hồ bơi ngoài trời.','Góc quay gần đi theo các em đang bơi với động tác đưa hai tay về trước.','Trước cảnh bơi là cuộc phỏng vấn người đàn ông mặc áo đen và cảnh các em bám thành hồ.'],'Phỏng vấn66–72, bám thành74–76, bơi78–84.','Chưa kiểm chứng chuyển động liên tục để gắn nhãn kiểu bơi; H3 thuộc context.')
add(73,[(44,59)],[(29,59)],['Đoạn quay xe đạp chuyển từ góc nhìn phía sau sang góc nhìn từ trên cao.','Nhóm gồm các tay đua áo vàng, áo chấm bi, áo sẫm và áo xanh.','Ở cảnh trên cao, bốn tay đua đi dọc một đoạn đường thẳng.'],'Sau cảnh cận40–42, chuyển trên cao khoảng44.','Chưa xác minh người áo xanh vượt và giữ vị trí tới cuối; cần mở rộng, không chấp nhận interval này như GT cuối.')
add(74,[(722,726)],[(710,726)],['Một slide bài giảng hóa học hiển thị câu hỏi trắc nghiệm về kim loại.','Các lựa chọn trên slide là Mg, Na, Al và Fe.','Bên dưới câu hỏi xuất hiện dòng Đáp án đúng là B.'],'Câu hỏi710–721, đáp án722, slide sau726.','Chỉ mô tả nội dung hiển thị, không kiểm chứng tính đúng của bài giảng; biên cần kiểm tra dày hơn.')
add(75,[(425,428),(431,439)],[(425,444)],['Một công trình có dạng vòng bầu dục được quay từ trên cao.','Công trình có màu vàng nâu, giữa là sân trồng cây.','Các cảnh sau quay khoảng sân bên trong và bức tường có nhiều ô mở.'],'Aerial425–427 và431–433; sân434–435; tường436–438.','Chưa thấy đủ hành lang, số lớp và shot cuối query; không suy chất liệu đất nung từ màu sắc.')
